Object.assign(apps,{converter:['Convertidor',420,350],backup:['Respaldos',440,340]});icons.converter=icons.calc;icons.backup=icons.files;
const toolsBody=body;body=function(id){if(id==='converter')return '<div class="extra-pad"><h2>Convertidor de unidades</h2><div class="convert-form"><label>Magnitud<select id="magnitude"><option value="length">Longitud</option><option value="mass">Masa</option><option value="temperature">Temperatura</option><option value="data">Datos</option></select></label><label>Cantidad<input type="number" id="convertvalue" value="1" step="any"></label><label>De<select id="convertfrom"></select></label><label>A<select id="convertto"></select></label></div><output id="convertresult"></output><button class="primary" id="swapunits">⇄ Intercambiar</button></div>';if(id==='backup')return '<div class="extra-pad"><h2>Tu escritorio, contigo.</h2><p>Exporta notas, documentos, pendientes, presupuesto, notas del calendario y preferencias a un archivo JSON.</p><button class="primary" id="exportbackup">↓ Exportar respaldo</button><hr><p>Importa un respaldo. Las claves incluidas reemplazarán los datos actuales; antes se descargará una copia de seguridad.</p><button class="primary" id="importbackup">↑ Importar respaldo</button><input id="backuppicker" type="file" accept=".json,application/json" hidden><small>Los archivos de “Mis archivos” y los dibujos no se incluyen.</small></div>';return toolsBody(id)};
const toolsSetup=setup;setup=function(id,w){toolsSetup(id,w);if(id==='converter'){const sets={length:{Metros:1,Kilómetros:1000,Centímetros:.01,Milímetros:.001,Pulgadas:.0254,Pies:.3048,Millas:1609.344},mass:{Kilogramos:1,Gramos:.001,Libras:.45359237,Onzas:.028349523125},temperature:{Celsius:1,Fahrenheit:1,Kelvin:1},data:{Bytes:1,KB:1000,MB:1000000,GB:1000000000,KiB:1024,MiB:1048576,GiB:1073741824}};let group=w.querySelector('#magnitude'),from=w.querySelector('#convertfrom'),to=w.querySelector('#convertto'),input=w.querySelector('#convertvalue'),result=w.querySelector('#convertresult');function convert(){if(input.value===''){result.textContent='Introduce una cantidad.';return}let n=Number(input.value),value;if(!Number.isFinite(n)){result.textContent='Cantidad no válida.';return}if(group.value==='temperature'){let c=from.value==='Celsius'?n:from.value==='Fahrenheit'?(n-32)*5/9:n-273.15;value=to.value==='Celsius'?c:to.value==='Fahrenheit'?c*9/5+32:c+273.15}else value=n*sets[group.value][from.value]/sets[group.value][to.value];result.textContent=Number.isFinite(value)?value.toLocaleString('es-MX',{maximumSignificantDigits:12})+' '+to.value:'Resultado fuera de rango.'}function options(){[from,to].forEach(el=>{el.replaceChildren();Object.keys(sets[group.value]).forEach(unit=>{let op=document.createElement('option');op.value=op.textContent=unit;el.append(op)})});to.selectedIndex=1;convert()}group.onchange=options;from.onchange=to.onchange=input.oninput=convert;w.querySelector('#swapunits').onclick=()=>{let a=from.value;from.value=to.value;to.value=a;convert()};options()}
if(id==='backup'){function snapshot(){let data={};for(let i=0;i<localStorage.length;i++){let key=localStorage.key(i);if(key.startsWith('papel-'))data[key]=localStorage.getItem(key)}return {app:'PAPEL OS',version:1,date:new Date().toISOString(),data}}function exportNow(name='papel-respaldo.json'){downloadBlob(new Blob([JSON.stringify(snapshot(),null,2)],{type:'application/json'}),name)}w.querySelector('#exportbackup').onclick=()=>{try{exportNow();toast('Respaldo descargado.')}catch{toast('No se pudo exportar el respaldo.')}};w.querySelector('#importbackup').onclick=()=>w.querySelector('#backuppicker').click();w.querySelector('#backuppicker').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('Archivo demasiado grande.');let obj=JSON.parse(await file.text());if(obj.app!=='PAPEL OS'||obj.version!==1||!obj.data||typeof obj.data!=='object'||Array.isArray(obj.data))throw Error('No es un respaldo válido de PAPEL OS.');const entries=Object.entries(obj.data);if(entries.some(([k,v])=>!k.startsWith('papel-')||typeof v!=='string'))throw Error('El respaldo contiene datos no válidos.');for(const [k,v] of entries){if(['papel-documents','papel-todos','papel-budget','papel-sticky'].includes(k)){const parsed=JSON.parse(v);if(!Array.isArray(parsed))throw Error('Formato de datos incorrecto.');if(k==='papel-documents'&&parsed.some(x=>!x||typeof x.id!=='string'||typeof x.name!=='string'||typeof x.text!=='string'))throw Error('Documentos no válidos.');if(k==='papel-todos'&&parsed.some(x=>!x||typeof x.text!=='string'||typeof x.done!=='boolean'))throw Error('Pendientes no válidos.');if(k==='papel-budget'&&parsed.some(x=>!x||typeof x.description!=='string'||!Number.isFinite(x.amount)||!['income','expense'].includes(x.type)))throw Error('Presupuesto no válido.');if(k==='papel-sticky'&&parsed.some(x=>!x||typeof x.id!=='string'||typeof x.text!=='string'||!Number.isFinite(x.x)||!Number.isFinite(x.y)))throw Error('Notas adhesivas no válidas.')}}let before=snapshot();exportNow('papel-antes-de-importar.json');try{entries.forEach(([k,v])=>localStorage.setItem(k,v))}catch(error){entries.forEach(([k])=>{if(k in before.data)localStorage.setItem(k,before.data[k]);else localStorage.removeItem(k)});throw Error('No hay espacio suficiente. Se conservaron los datos anteriores.')}toast('Respaldo importado. Recarga para aplicar los cambios.');const reload=document.createElement('button');reload.className='primary';reload.textContent='Recargar escritorio';reload.onclick=()=>location.reload();w.querySelector('.extra-pad').append(reload)}catch(error){toast(error.message||'No se pudo importar.')}e.target.value=''}}};
let sticky;try{sticky=JSON.parse(read('papel-sticky','[]'))}catch{sticky=[]}if(!Array.isArray(sticky))sticky=[];function saveSticky(){save('papel-sticky',JSON.stringify(sticky))}function showSticky(item){const el=document.createElement('section');el.className='sticky';el.style.left=Math.max(0,Math.min(innerWidth-210,item.x))+'px';el.style.top=Math.max(34,Math.min(innerHeight-230,item.y))+'px';const bar=document.createElement('div');bar.className='sticky-bar';bar.textContent='Nota rápida';const close=document.createElement('button');close.textContent='×';close.setAttribute('aria-label','Guardar y ocultar nota');bar.append(close);const area=document.createElement('textarea');area.setAttribute('aria-label','Nota adhesiva');area.placeholder='Una idea rápida…';area.value=item.text;area.oninput=()=>{item.text=area.value;saveSticky()};close.onclick=()=>{el.remove();toast('Nota guardada. Reábrela desde Notas rápidas.');item.hidden=true;saveSticky()};let x,y,left,top;bar.onpointerdown=e=>{if(e.target.closest('button'))return;x=e.clientX;y=e.clientY;left=el.offsetLeft;top=el.offsetTop;bar.setPointerCapture(e.pointerId);bar.onpointermove=p=>{item.x=Math.max(0,Math.min(innerWidth-200,left+p.clientX-x));item.y=Math.max(32,Math.min(innerHeight-210,top+p.clientY-y));el.style.left=item.x+'px';el.style.top=item.y+'px'};bar.onpointerup=()=>{bar.onpointermove=null;saveSticky()}};el.append(bar,area);$('#desktop').append(el)}sticky.filter(s=>!s.hidden).forEach(showSticky);function addSticky(){let hidden=sticky.filter(s=>s.hidden);if(hidden.length){hidden.forEach(s=>{s.hidden=false;showSticky(s)});saveSticky();return}const item={id:crypto.randomUUID(),text:'',x:Math.max(20,innerWidth-255),y:65+sticky.length%4*35,hidden:false};sticky.push(item);saveSticky();showSticky(item)}
['converter','backup'].forEach(id=>{const shortcut=document.createElement('button');shortcut.className='desktop-icon';shortcut.dataset.open=id;shortcut.innerHTML=svg(id)+`<span>${apps[id][0]}</span>`;$('#icons').append(shortcut);let b=document.createElement('button');b.dataset.open=id;b.textContent='↗   '+apps[id][0];$('#startapps').append(b)});let stickyMenu=document.createElement('button');stickyMenu.textContent='▤   Notas rápidas (nueva / reabrir)';stickyMenu.onclick=()=>{addSticky();$('#start').hidden=true};$('#startapps').append(stickyMenu);const quick=document.createElement('button');quick.id='quicksticky';quick.textContent='＋ Nota';quick.title='Nueva nota adhesiva o reabrir notas ocultas';quick.onclick=addSticky;$('#showdesktop').before(quick);
